(() => {
  (typeof ngDevMode === "undefined" || ngDevMode) && setClassMetadata(ProjectManager, [{
    type: Component,
    args: [{ selector: "app-project-manager", imports: [CommonModule, FormsModule], template: `<div class="max-w-7xl mx-auto p-5">\r
 \r
  <div class="flex justify-between items-center mb-8 pb-5 border-b-2 border-gray-200">\r
    <h1 class="text-3xl font-bold text-gray-800">Project Management</h1>\r
    <button \r
      class="px-5 py-2.5 bg-blue-600 text-white rounded-lg font-medium uppercase tracking-wide transition-all duration-300 hover:bg-blue-700 hover:-translate-y-0.5 hover:shadow-lg disabled:opacity-60 disabled:cursor-not-allowed disabled:transform-none" \r
      (click)="toggleCreateProjectForm()" \r
      *ngIf="!selectedProject"\r
      [disabled]="loading">\r
      <span *ngIf="!showCreateProjectForm">+ Create New Project</span>\r
      <span *ngIf="showCreateProjectForm && !isEditMode">Cancel</span>\r
      <span *ngIf="showCreateProjectForm && isEditMode">Cancel Edit</span>\r
    </button>\r
    <button \r
      class="px-5 py-2.5 bg-gray-600 text-white rounded-lg font-medium uppercase tracking-wide transition-all duration-300 hover:bg-gray-700 hover:-translate-y-0.5 hover:shadow-lg" \r
      (click)="backToProjectsList()" \r
      *ngIf="selectedProject">\r
      \u2190 Back to Projects\r
    </button>\r
  </div>\r
\r
 \r
  <div class="p-4 mb-5 bg-green-100 text-green-800 border border-green-200 rounded-lg animate-slideDown" *ngIf="successMessage">\r
    {{ successMessage }}\r
  </div>\r
\r
 \r
  <div class="p-4 mb-5 bg-red-100 text-red-800 border border-red-200 rounded-lg relative" *ngIf="error">\r
    {{ error }}\r
    <button class="absolute right-2 top-1/2 -translate-y-1/2 bg-transparent border-none text-2xl cursor-pointer text-red-800 hover:opacity-70" (click)="error = null">\xD7</button>\r
  </div>\r
\r
 \r
  <div class="bg-gray-50 p-6 rounded-lg mb-8 shadow-sm" *ngIf="showCreateProjectForm && !selectedProject">\r
    <h2 class="text-xl font-semibold text-gray-800 mb-5">{{ isEditMode ? 'Edit Project' : 'Create New Project' }}</h2>\r
    <form (ngSubmit)="isEditMode ? updateProject() : createProject()">\r
      <div class="grid grid-cols-1 md:grid-cols-2 gap-5">\r
      \r
        <div class="mb-5">\r
          <label for="projectName" class="block mb-2 text-gray-700 font-medium">Project Name *</label>\r
          <input \r
            type="text" \r
            id="projectName" \r
            [(ngModel)]="newProject.name" \r
            name="projectName"\r
            placeholder="Enter project name"\r
            required\r
            class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-gray-200 disabled:cursor-not-allowed"\r
            [disabled]="loading">\r
        </div>\r
\r
    \r
        <div class="mb-5">\r
          <label for="projectManager" class="block mb-2 text-gray-700 font-medium">Project Manager *</label>\r
          <select \r
            id="projectManager" \r
            [(ngModel)]="newProject.projectManagerId" \r
            name="projectManagerId"\r
            required\r
            class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-gray-200 disabled:cursor-not-allowed"\r
            [disabled]="loading">\r
            <option [value]="0" disabled>Select a project manager</option>\r
            <option *ngFor="let user of users" [value]="user.id">{{ user.firstName }} {{ user.lastName }}</option>\r
          </select>\r
        </div>\r
      </div>\r
\r
      <div class="mb-5">\r
        <label for="description" class="block mb-2 text-gray-700 font-medium">Description</label>\r
        <textarea \r
          id="description" \r
          [(ngModel)]="newProject.description" \r
          name="description"\r
          placeholder="Enter project description"\r
          rows="3"\r
          class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-gray-200 disabled:cursor-not-allowed"\r
          [disabled]="loading"></textarea>\r
      </div>\r
\r
      <div class="grid grid-cols-1 md:grid-cols-2 gap-5">\r
      \r
        <div class="mb-5">\r
          <label for="startDate" class="block mb-2 text-gray-700 font-medium">Start Date *</label>\r
          <input \r
            type="date" \r
            id="startDate" \r
            [(ngModel)]="newProject.startDate" \r
            name="startDate"\r
            required\r
            class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-gray-200 disabled:cursor-not-allowed"\r
            [disabled]="loading">\r
        </div>\r
\r
       \r
        <div class="mb-5">\r
          <label for="endDate" class="block mb-2 text-gray-700 font-medium">End Date *</label>\r
          <input \r
            type="date" \r
            id="endDate" \r
            [(ngModel)]="newProject.endDate" \r
            name="endDate"\r
            required\r
            class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-gray-200 disabled:cursor-not-allowed"\r
            [disabled]="loading">\r
        </div>\r
      </div>\r
\r
      <div class="grid grid-cols-1 md:grid-cols-3 gap-5">\r
       \r
        <div class="mb-5">\r
          <label for="estimatedDuration" class="block mb-2 text-gray-700 font-medium">Estimated Duration (days)</label>\r
          <input \r
            type="number" \r
            id="estimatedDuration" \r
            [(ngModel)]="newProject.estimatedDuration" \r
            name="estimatedDuration"\r
            placeholder="0"\r
            min="0"\r
            class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-gray-200 disabled:cursor-not-allowed"\r
            [disabled]="loading">\r
        </div>\r
\r
        <div class="mb-5">\r
          <label for="serviceId" class="block mb-2 text-gray-700 font-medium">Service</label>\r
          <select \r
            id="serviceId" \r
            [(ngModel)]="newProject.serviceId" \r
            name="serviceId"\r
            class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-gray-200 disabled:cursor-not-allowed"\r
            [disabled]="loading">\r
            <option [value]="undefined">No service</option>\r
            <option *ngFor="let service of services" [value]="service.id">{{ service.name }}</option>\r
          </select>\r
        </div>\r
\r
     \r
        <div class="mb-5">\r
          <label for="teamId" class="block mb-2 text-gray-700 font-medium">Team</label>\r
          <select \r
            id="teamId" \r
            [(ngModel)]="newProject.teamId" \r
            name="teamId"\r
            class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-gray-200 disabled:cursor-not-allowed"\r
            [disabled]="loading">\r
            <option [value]="undefined">No team</option>\r
            <option *ngFor="let team of teams" [value]="team.id">{{ team.name }}</option>\r
          </select>\r
        </div>\r
      </div>\r
\r
    \r
      <div class="mb-5">\r
        <label for="projectState" class="block mb-2 text-gray-700 font-medium">Project State *</label>\r
        <select \r
          id="projectState" \r
          [(ngModel)]="newProject.projectState" \r
          name="projectState"\r
          required\r
          class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100 disabled:bg-gray-200 disabled:cursor-not-allowed"\r
          [disabled]="loading">\r
          <option *ngFor="let state of stateOptions" [ngValue]="state.value">{{ state.label }}</option>\r
        </select>\r
      </div>\r
\r
      <div class="flex gap-2.5 mt-5">\r
        <button type="submit" class="px-5 py-2.5 bg-blue-600 text-white rounded-lg font-medium uppercase tracking-wide transition-all duration-300 hover:bg-blue-700 disabled:opacity-60 disabled:cursor-not-allowed" [disabled]="loading">\r
          {{ isEditMode ? 'Update Project' : 'Create Project' }}\r
        </button>\r
        <button type="button" class="px-5 py-2.5 bg-gray-600 text-white rounded-lg font-medium uppercase tracking-wide transition-all duration-300 hover:bg-gray-700 disabled:opacity-60 disabled:cursor-not-allowed" (click)="toggleCreateProjectForm()" [disabled]="loading">\r
          Cancel\r
        </button>\r
      </div>\r
    </form>\r
  </div>\r
\r
\r
  <div *ngIf="!selectedProject && !showCreateProjectForm">\r
    <h2 class="text-2xl font-semibold text-gray-800 mb-5">All Projects ({{ projects.length }})</h2>\r
    \r
\r
    <div class="flex justify-center items-center py-20" *ngIf="loading">\r
      <div class="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>\r
    </div>\r
\r
   \r
    <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5 mb-8" *ngIf="projects.length > 0 && !loading">\r
      <div class="bg-white border border-gray-200 rounded-lg p-5 transition-all duration-300 hover:-translate-y-1 hover:shadow-lg" *ngFor="let project of projects">\r
        <div class="flex justify-between items-start mb-4 pb-4 border-b border-gray-200">\r
          <h3 class="text-xl font-semibold text-gray-800">{{ project.name }}</h3>\r
          <span class="bg-blue-600 text-white px-2 py-1 rounded text-xs font-medium">{{ getStateName(project.projectState) }}</span>\r
        </div>\r
        \r
        <div class="mb-4 space-y-2">\r
          <p class="text-gray-600 text-sm"><strong>PM:</strong> {{ getUserName(project.projectManagerId) }}</p>\r
          <p class="text-gray-600 text-sm" *ngIf="project.description">\r
            <strong>Description:</strong> {{ project.description.length > 60 ? project.description.substring(0, 60) + '...' : project.description }}\r
          </p>\r
          <p class="text-gray-600 text-sm"><strong>Service:</strong> {{ getServiceName(project.serviceId) }}</p>\r
          <p class="text-gray-600 text-sm"><strong>Team:</strong> {{ getTeamName(project.teamId) }}</p>\r
          <p class="text-gray-600 text-sm"><strong>Duration:</strong> {{ project.estimatedDuration }} days</p>\r
          <p class="text-gray-600 text-sm"><strong>Start:</strong> {{ formatDate(project.startDate) }}</p>\r
          <p class="text-gray-600 text-sm"><strong>End:</strong> {{ formatDate(project.endDate) }}</p>\r
        </div>\r
        \r
        <div class="flex gap-2.5">\r
          <button class="flex-1 px-4 py-2 bg-cyan-600 text-white rounded-lg font-medium text-sm uppercase tracking-wide transition-all duration-300 hover:bg-cyan-700 disabled:opacity-60 disabled:cursor-not-allowed" (click)="viewProjectDetails(project)" [disabled]="loading">\r
            View Details\r
          </button>\r
          <button class="flex-1 px-4 py-2 bg-yellow-600 text-white rounded-lg font-medium text-sm uppercase tracking-wide transition-all duration-300 hover:bg-yellow-700 disabled:opacity-60 disabled:cursor-not-allowed" (click)="startEditProject(project)" [disabled]="loading">\r
            Edit\r
          </button>\r
          <button class="flex-1 px-4 py-2 bg-red-600 text-white rounded-lg font-medium text-sm uppercase tracking-wide transition-all duration-300 hover:bg-red-700 disabled:opacity-60 disabled:cursor-not-allowed" (click)="deleteProject(project.id!)" [disabled]="loading">\r
            Delete\r
          </button>\r
        </div>\r
      </div>\r
    </div>\r
\r
    \r
    <div class="text-center py-20 text-gray-500" *ngIf="projects.length === 0 && !loading">\r
      <p class="text-xl mb-2">No projects found</p>\r
      <p>Click "Create New Project" to add your first project</p>\r
    </div>\r
  </div>\r
\r
 \r
  <div *ngIf="selectedProject" class="space-y-6">\r
    <section class="bg-white rounded-2xl shadow border border-gray-200 p-6">\r
      <p class="text-gray-500 text-sm mb-4">{{ currentDateLabel }}</p>\r
\r
      <div class="flex flex-col md:flex-row md:items-center md:justify-between gap-4 pb-5 border-b border-gray-200">\r
        <div>\r
          <div class="flex items-center gap-3 mb-1">\r
            <h2 class="text-3xl font-bold text-slate-900">{{ selectedProject.name }}</h2>\r
            <span class="px-4 py-1 rounded-full font-semibold text-sm" [ngClass]="getStatusBadgeClasses(selectedProject.projectState)">{{ getStateLabel(selectedProject.projectState) }}</span>\r
          </div>\r
          <p class="text-lg text-slate-600 mb-1">{{ selectedProject.description || 'Aucune description' }}</p>\r
          <p class="text-lg text-slate-600">Service: {{ getServiceName(selectedProject.serviceId) }}</p>\r
        </div>\r
      </div>\r
\r
      <div class="grid grid-cols-2 md:grid-cols-4 gap-6 py-6 border-b border-gray-200">\r
        <div>\r
          <p class="text-3xl font-bold text-slate-900">{{ getProjectUserStoriesCount(selectedProject) }}</p>\r
          <p class="text-base text-slate-600">User Stories</p>\r
        </div>\r
        <div>\r
          <p class="text-3xl font-bold text-slate-900">{{ getProjectSprintsCount(selectedProject) }}</p>\r
          <p class="text-base text-slate-600">Sprints</p>\r
        </div>\r
        <div>\r
          <p class="text-3xl font-bold text-slate-900">{{ getProjectTasksCount(selectedProject) }}</p>\r
          <p class="text-base text-slate-600">T\xE2ches</p>\r
        </div>\r
        <div>\r
          <p class="text-3xl font-bold text-slate-900">{{ getProjectMembersCount(selectedProject) }}</p>\r
          <p class="text-base text-slate-600">Membres</p>\r
        </div>\r
      </div>\r
\r
      <div class="pt-5">\r
        <div class="flex items-center justify-between mb-2">\r
          <p class="text-lg text-slate-700">Progression globale</p>\r
          <span class="text-lg font-semibold text-slate-900">{{ getProjectProgress(selectedProject) }}%</span>\r
        </div>\r
        <div class="h-3 bg-gray-200 rounded-full overflow-hidden">\r
          <div class="h-full bg-blue-500" [style.width.%]="getProjectProgress(selectedProject)"></div>\r
        </div>\r
      </div>\r
    </section>\r
\r
    <section class="bg-white rounded-2xl shadow border border-gray-200 overflow-hidden">\r
      <div class="flex border-b border-gray-200">\r
        <button class="px-6 py-4 text-base font-semibold text-slate-500 transition-colors" [class.text-blue-600]="detailTab === 'overview'" [class.border-b-2]="detailTab === 'overview'" [class.border-blue-600]="detailTab === 'overview'" (click)="setDetailTab('overview')">\r
          Vue d'ensemble\r
        </button>\r
        <button class="px-6 py-4 text-base font-semibold text-slate-500 transition-colors" [class.text-blue-600]="detailTab === 'stories'" [class.border-b-2]="detailTab === 'stories'" [class.border-blue-600]="detailTab === 'stories'" (click)="setDetailTab('stories')">\r
          User Stories ({{ getProjectUserStoriesCount(selectedProject) }})\r
        </button>\r
        <button class="px-6 py-4 text-base font-semibold text-slate-500 transition-colors" [class.text-blue-600]="detailTab === 'sprints'" [class.border-b-2]="detailTab === 'sprints'" [class.border-blue-600]="detailTab === 'sprints'" (click)="setDetailTab('sprints')">\r
          Sprints ({{ getProjectSprintsCount(selectedProject) }})\r
        </button>\r
      </div>\r
\r
      <div class="p-6" *ngIf="detailTab === 'overview'">\r
        <div class="grid grid-cols-1 md:grid-cols-2 gap-8">\r
          <div>\r
            <h3 class="text-2xl font-bold text-slate-900 mb-4">Informations du projet</h3>\r
            <div class="space-y-2 text-base">\r
              <p><span class="text-slate-500">Date de d\xE9but:</span> <strong class="ml-2 text-slate-900">{{ formatDate(selectedProject.startDate) }}</strong></p>\r
              <p><span class="text-slate-500">Date de fin:</span> <strong class="ml-2 text-slate-900">{{ formatDate(selectedProject.endDate) }}</strong></p>\r
              <p><span class="text-slate-500">Chef de projet:</span> <strong class="ml-2 text-slate-900">{{ getUserName(selectedProject.projectManagerId) }}</strong></p>\r
            </div>\r
          </div>\r
\r
          <div>\r
            <h3 class="text-2xl font-bold text-slate-900 mb-4">\xC9quipe</h3>\r
            <div class="flex flex-wrap gap-3">\r
              <div *ngFor="let member of selectedProjectMembers" class="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-slate-100 text-slate-800">\r
                <span class="w-8 h-8 rounded-full bg-blue-100 text-blue-700 flex items-center justify-center text-sm font-semibold">{{ getMemberInitials(member) }}</span>\r
                <span class="text-base">{{ member.firstName }} {{ member.lastName }}</span>\r
              </div>\r
              <p *ngIf="selectedProjectMembers.length === 0" class="text-slate-500">Aucun membre assign\xE9.</p>\r
            </div>\r
          </div>\r
        </div>\r
\r
        <button type="button" class="mt-8 w-full py-3 rounded-xl bg-blue-600 hover:bg-blue-700 text-white text-lg font-semibold" (click)="openKanbanBoard()">\r
          Voir le tableau Kanban des t\xE2ches\r
        </button>\r
      </div>\r
\r
      <div class="p-6" *ngIf="detailTab === 'stories'">\r
        <div class="flex justify-between items-center mb-4">\r
          <h3 class="text-2xl font-bold text-slate-900">Project User Stories</h3>\r
          <button class="px-4 py-2 bg-blue-600 text-white rounded-lg font-medium text-sm uppercase tracking-wide transition-all duration-300 hover:bg-blue-700" (click)="toggleDetailUserStoryForm()" [disabled]="loading">\r
            <span *ngIf="!showCreateUserStoryFormInDetails">+ Create User Story</span>\r
            <span *ngIf="showCreateUserStoryFormInDetails && !isEditingUserStoryInDetails">Cancel</span>\r
            <span *ngIf="showCreateUserStoryFormInDetails && isEditingUserStoryInDetails">Cancel Edit</span>\r
          </button>\r
        </div>\r
\r
        <div class="bg-gray-50 p-5 rounded-lg border border-gray-200 mb-5" *ngIf="showCreateUserStoryFormInDetails">\r
          <h4 class="text-xl font-semibold text-gray-800 mb-4">{{ isEditingUserStoryInDetails ? 'Edit User Story' : 'Create User Story' }}</h4>\r
          <form (ngSubmit)="isEditingUserStoryInDetails ? updateDetailUserStory() : createDetailUserStory()">\r
            <div class="grid grid-cols-1 md:grid-cols-2 gap-4">\r
              <div class="mb-4">\r
                <label for="storyName" class="block mb-2 text-gray-700 font-medium">Name *</label>\r
                <input\r
                  type="text"\r
                  id="storyName"\r
                  [(ngModel)]="newDetailUserStory.name"\r
                  name="storyName"\r
                  required\r
                  class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"\r
                  [disabled]="loading">\r
              </div>\r
\r
              <div class="mb-4">\r
                <label for="storySprint" class="block mb-2 text-gray-700 font-medium">Sprint *</label>\r
                <select\r
                  id="storySprint"\r
                  [(ngModel)]="newDetailUserStory.sprintId"\r
                  name="storySprint"\r
                  required\r
                  class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"\r
                  [disabled]="loading || projectSprints.length === 0">\r
                  <option value="" disabled>Select sprint</option>\r
                  <option *ngFor="let sprint of projectSprints" [value]="sprint.id">{{ sprint.name }}</option>\r
                </select>\r
              </div>\r
            </div>\r
\r
            <div class="mb-4">\r
              <label for="storyDescription" class="block mb-2 text-gray-700 font-medium">Description</label>\r
              <textarea\r
                id="storyDescription"\r
                [(ngModel)]="newDetailUserStory.description"\r
                name="storyDescription"\r
                rows="3"\r
                class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"\r
                [disabled]="loading"></textarea>\r
            </div>\r
\r
            <div class="grid grid-cols-1 md:grid-cols-4 gap-4">\r
              <div class="mb-4">\r
                <label for="storyStartDate" class="block mb-2 text-gray-700 font-medium">Start Date *</label>\r
                <input\r
                  type="date"\r
                  id="storyStartDate"\r
                  [(ngModel)]="newDetailUserStory.startDate"\r
                  name="storyStartDate"\r
                  class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"\r
                  [disabled]="loading">\r
              </div>\r
\r
              <div class="mb-4">\r
                <label for="storyEndDate" class="block mb-2 text-gray-700 font-medium">End Date *</label>\r
                <input\r
                  type="date"\r
                  id="storyEndDate"\r
                  [(ngModel)]="newDetailUserStory.endDate"\r
                  name="storyEndDate"\r
                  class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"\r
                  [disabled]="loading">\r
              </div>\r
\r
              <div class="mb-4">\r
                <label for="storyEstimatedDuration" class="block mb-2 text-gray-700 font-medium">Estimated Duration (days)</label>\r
                <input\r
                  type="number"\r
                  id="storyEstimatedDuration"\r
                  [(ngModel)]="newDetailUserStory.estimatedDuration"\r
                  name="storyEstimatedDuration"\r
                  min="1"\r
                  class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"\r
                  [disabled]="loading">\r
              </div>\r
\r
              <div class="mb-4">\r
                <label for="storyStatus" class="block mb-2 text-gray-700 font-medium">Status</label>\r
                <select\r
                  id="storyStatus"\r
                  [(ngModel)]="newDetailUserStory.userStoryState"\r
                  name="storyStatus"\r
                  class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"\r
                  [disabled]="loading">\r
                  <option *ngFor="let state of userStoryStateOptions" [ngValue]="state.value">{{ state.label }}</option>\r
                </select>\r
              </div>\r
            </div>\r
\r
            <div class="flex gap-2.5 mt-4">\r
              <button type="submit" class="px-4 py-2 bg-blue-600 text-white rounded-lg font-medium text-sm uppercase tracking-wide transition-all duration-300 hover:bg-blue-700 disabled:opacity-60 disabled:cursor-not-allowed" [disabled]="loading || projectSprints.length === 0">\r
                {{ isEditingUserStoryInDetails ? 'Update User Story' : 'Create User Story' }}\r
              </button>\r
              <button type="button" class="px-4 py-2 bg-gray-600 text-white rounded-lg font-medium text-sm uppercase tracking-wide transition-all duration-300 hover:bg-gray-700 disabled:opacity-60 disabled:cursor-not-allowed" (click)="toggleDetailUserStoryForm()" [disabled]="loading">\r
                Cancel\r
              </button>\r
            </div>\r
          </form>\r
        </div>\r
\r
        <div *ngIf="projectSprints.length === 0" class="p-4 mb-4 bg-amber-100 text-amber-800 border border-amber-200 rounded-lg">\r
          Create at least one sprint before creating a user story.\r
        </div>\r
\r
        <h3 class="text-xl font-bold text-slate-900 mb-4">Liste des User Stories</h3>\r
        <div *ngIf="projectUserStories.length === 0" class="text-slate-500 text-base">Aucune user story pour ce projet.</div>\r
        <div *ngFor="let story of projectUserStories" class="p-4 border border-gray-200 rounded-xl mb-3 bg-white shadow-sm">\r
          <div class="flex justify-between items-start gap-3 mb-2">\r
            <div class="flex items-center gap-3">\r
              <p class="font-semibold text-slate-900 text-lg leading-none">{{ story.name || story.title }}</p>\r
              <span class="px-2.5 py-1 rounded-full text-xs font-medium" [ngClass]="getUserStoryStatusBadgeClasses(story)">{{ getUserStoryStatusDisplay(story) }}</span>\r
            </div>\r
\r
            <div class="relative">\r
              <button class="w-8 h-8 rounded-lg bg-gray-100 text-gray-500 text-lg font-bold hover:bg-gray-200" (click)="toggleUserStoryMenu(story.id)">\u22EE</button>\r
              <div *ngIf="openUserStoryMenuId === story.id" class="absolute right-0 mt-2 w-40 bg-white border border-gray-200 rounded-xl shadow-lg z-10 p-1.5">\r
                <button class="w-full text-left px-2.5 py-1.5 text-sm text-slate-800 hover:bg-slate-100 rounded-lg" (click)="startEditDetailUserStory(story); closeUserStoryMenu()">Modifier</button>\r
                <button class="w-full text-left px-2.5 py-1.5 text-sm text-red-600 hover:bg-red-50 rounded-lg" (click)="deleteDetailUserStory(story.id); closeUserStoryMenu()">Supprimer</button>\r
              </div>\r
            </div>\r
          </div>\r
\r
          <p class="text-slate-700 text-sm mb-4">Description: {{ story.description || 'Aucune description' }}</p>\r
\r
          <div class="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">\r
            <div>\r
              <p class="text-slate-500 mb-0.5">D\xE9but:</p>\r
              <p class="font-semibold text-slate-900">{{ story.startDate ? formatDate(story.startDate) : '-' }}</p>\r
            </div>\r
            <div>\r
              <p class="text-slate-500 mb-0.5">Fin:</p>\r
              <p class="font-semibold text-slate-900">{{ story.endDate ? formatDate(story.endDate) : '-' }}</p>\r
            </div>\r
            <div>\r
              <p class="text-slate-500 mb-0.5">Dur\xE9e estim\xE9e:</p>\r
              <p class="font-semibold text-slate-900">{{ story.estimatedDuration ?? '-' }} j</p>\r
            </div>\r
            <div>\r
              <p class="text-slate-500 mb-0.5">Sprint:</p>\r
              <p class="font-semibold text-slate-900">#{{ story.sprintId }}</p>\r
            </div>\r
          </div>\r
        </div>\r
      </div>\r
\r
      <div class="p-6" *ngIf="detailTab === 'sprints'">\r
        <div class="flex justify-between items-center mb-4">\r
          <h3 class="text-2xl font-bold text-slate-900">Project Sprints</h3>\r
          <button class="px-4 py-2 bg-blue-600 text-white rounded-lg font-medium text-sm uppercase tracking-wide transition-all duration-300 hover:bg-blue-700" (click)="toggleDetailSprintForm()" [disabled]="loading">\r
            <span *ngIf="!showCreateSprintFormInDetails">+ Create Sprint</span>\r
            <span *ngIf="showCreateSprintFormInDetails && !isEditingSprintInDetails">Cancel</span>\r
            <span *ngIf="showCreateSprintFormInDetails && isEditingSprintInDetails">Cancel Edit</span>\r
          </button>\r
        </div>\r
\r
        <div class="bg-gray-50 p-5 rounded-lg border border-gray-200 mb-5" *ngIf="showCreateSprintFormInDetails">\r
          <h4 class="text-xl font-semibold text-gray-800 mb-4">{{ isEditingSprintInDetails ? 'Edit Sprint' : 'Create Sprint' }}</h4>\r
          <form (ngSubmit)="isEditingSprintInDetails ? updateDetailSprint() : createDetailSprint()">\r
            <div class="grid grid-cols-1 md:grid-cols-2 gap-4">\r
              <div class="mb-4">\r
                <label for="detailSprintName" class="block mb-2 text-gray-700 font-medium">Sprint Name *</label>\r
                <input\r
                  type="text"\r
                  id="detailSprintName"\r
                  [(ngModel)]="newDetailSprint.name"\r
                  name="detailSprintName"\r
                  required\r
                  class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"\r
                  [disabled]="loading">\r
              </div>\r
\r
              <div class="mb-4">\r
                <label for="detailSprintState" class="block mb-2 text-gray-700 font-medium">Sprint State *</label>\r
                <select\r
                  id="detailSprintState"\r
                  [(ngModel)]="newDetailSprint.sprintState"\r
                  name="detailSprintState"\r
                  required\r
                  class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"\r
                  [disabled]="loading">\r
                  <option *ngFor="let state of sprintStateOptions" [ngValue]="state.value">{{ state.label }}</option>\r
                </select>\r
              </div>\r
            </div>\r
\r
            <div class="mb-4">\r
              <label for="detailSprintDescription" class="block mb-2 text-gray-700 font-medium">Description</label>\r
              <textarea\r
                id="detailSprintDescription"\r
                [(ngModel)]="newDetailSprint.description"\r
                name="detailSprintDescription"\r
                rows="3"\r
                class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"\r
                [disabled]="loading"></textarea>\r
            </div>\r
\r
            <div class="grid grid-cols-1 md:grid-cols-3 gap-4">\r
              <div class="mb-4">\r
                <label for="detailSprintStartDate" class="block mb-2 text-gray-700 font-medium">Start Date *</label>\r
                <input\r
                  type="date"\r
                  id="detailSprintStartDate"\r
                  [(ngModel)]="newDetailSprint.startDate"\r
                  name="detailSprintStartDate"\r
                  required\r
                  class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"\r
                  [disabled]="loading">\r
              </div>\r
\r
              <div class="mb-4">\r
                <label for="detailSprintEndDate" class="block mb-2 text-gray-700 font-medium">End Date *</label>\r
                <input\r
                  type="date"\r
                  id="detailSprintEndDate"\r
                  [(ngModel)]="newDetailSprint.endDate"\r
                  name="detailSprintEndDate"\r
                  required\r
                  class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"\r
                  [disabled]="loading">\r
              </div>\r
\r
              <div class="mb-4">\r
                <label for="detailSprintDuration" class="block mb-2 text-gray-700 font-medium">Estimated Duration (days)</label>\r
                <input\r
                  type="number"\r
                  id="detailSprintDuration"\r
                  [(ngModel)]="newDetailSprint.estimatedDuration"\r
                  name="detailSprintDuration"\r
                  min="0"\r
                  class="w-full px-3 py-2.5 border border-gray-300 rounded text-sm focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"\r
                  [disabled]="loading">\r
              </div>\r
            </div>\r
\r
            <div class="flex gap-2.5 mt-4">\r
              <button type="submit" class="px-4 py-2 bg-blue-600 text-white rounded-lg font-medium text-sm uppercase tracking-wide transition-all duration-300 hover:bg-blue-700 disabled:opacity-60 disabled:cursor-not-allowed" [disabled]="loading">\r
                {{ isEditingSprintInDetails ? 'Update Sprint' : 'Create Sprint' }}\r
              </button>\r
              <button type="button" class="px-4 py-2 bg-gray-600 text-white rounded-lg font-medium text-sm uppercase tracking-wide transition-all duration-300 hover:bg-gray-700 disabled:opacity-60 disabled:cursor-not-allowed" (click)="toggleDetailSprintForm()" [disabled]="loading">\r
                Cancel\r
              </button>\r
            </div>\r
          </form>\r
        </div>\r
\r
        <h3 class="text-xl font-bold text-slate-900 mb-4">Liste des Sprints</h3>\r
        <div *ngIf="projectSprints.length === 0" class="text-slate-500 text-base">Aucun sprint pour ce projet.</div>\r
        <div *ngFor="let sprint of projectSprints" class="p-4 border border-gray-200 rounded-xl mb-3 bg-white shadow-sm">\r
          <div class="flex justify-between items-start gap-3 mb-2">\r
            <div class="flex items-center gap-3">\r
              <p class="font-semibold text-slate-900 text-lg leading-none">{{ sprint.name }}</p>\r
              <span class="px-2.5 py-1 rounded-full text-xs font-medium" [ngClass]="getSprintStatusBadgeClasses(sprint.sprintState)">{{ getSprintStateName(sprint.sprintState) }}</span>\r
            </div>\r
\r
            <div class="relative">\r
              <button class="w-8 h-8 rounded-lg bg-gray-100 text-gray-500 text-lg font-bold hover:bg-gray-200" (click)="toggleSprintMenu(sprint.id)">\u22EE</button>\r
              <div *ngIf="openSprintMenuId === sprint.id" class="absolute right-0 mt-2 w-40 bg-white border border-gray-200 rounded-xl shadow-lg z-10 p-1.5">\r
       \r
                <button class="w-full text-left px-2.5 py-1.5 text-sm text-slate-800 hover:bg-slate-100 rounded-lg" (click)="startEditDetailSprint(sprint); closeSprintMenu()">Modifier</button>\r
                <button class="w-full text-left px-2.5 py-1.5 text-sm text-red-600 hover:bg-red-50 rounded-lg" (click)="deleteDetailSprint(sprint.id); closeSprintMenu()">Supprimer</button>\r
              </div>\r
            </div>\r
          </div>\r
\r
          <p class="text-slate-700 text-sm mb-4">Description: {{ sprint.description || 'Aucune description' }}</p>\r
\r
          <div class="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">\r
            <div>\r
              <p class="text-slate-500 mb-0.5">D\xE9but:</p>\r
              <p class="font-semibold text-slate-900">{{ formatDate(sprint.startDate) }}</p>\r
            </div>\r
            <div>\r
              <p class="text-slate-500 mb-0.5">Fin:</p>\r
              <p class="font-semibold text-slate-900">{{ formatDate(sprint.endDate) }}</p>\r
            </div>\r
            <div>\r
              <p class="text-slate-500 mb-0.5">Estimated Duration:</p>\r
              <p class="font-semibold text-slate-900">{{ sprint.estimatedDuration }} j</p>\r
            </div>\r
            <div>\r
              <p class="text-slate-500 mb-0.5">ID Sprint:</p>\r
              <p class="font-semibold text-slate-900">#{{ sprint.id }}</p>\r
            </div>\r
          </div>\r
        </div>\r
      </div>\r
    </section>\r
\r
    <div class="flex gap-3">\r
      <button class="px-5 py-2.5 bg-yellow-600 text-white rounded-lg font-medium uppercase tracking-wide transition-all duration-300 hover:bg-yellow-700" (click)="startEditProject(selectedProject); backToProjectsList()">\r
        Edit Project\r
      </button>\r
      <button class="px-5 py-2.5 bg-red-600 text-white rounded-lg font-medium uppercase tracking-wide transition-all duration-300 hover:bg-red-700" (click)="deleteProject(selectedProject.id!); backToProjectsList()">\r
        Delete Project\r
      </button>\r
    </div>\r
  </div>\r
</div>\r
` }]
  }], null, null);
})();
